if($type==='driver'){$packages=$data['packages']??[];if($package!==null){$found=false;foreach($packages as $name=>$p){$option=is_string($name)?$name:($p['option']??$p['id']??null);if($option===$package){$found=true;$amount=(int)($p['priceMinor']??$p['priceCents']??(is_numeric($p)?$p:$amount));break;}}if(!$found)fail(422,'VALIDATION_ERROR','The request contains invalid data.',['packageOption'=>['The package is not offered by this service.']]);}$passengers=(int)($search['passengers']??0);$seats=(int)($data['seats']??$data['capacity']??0);if($passengers<1||($seats>0&&$passengers>$seats))fail(409,'SERVICE_UNAVAILABLE','The selected vehicle cannot carry this party.');}
else{$hours=(int)($search['hours']??0);if(!in_array($hours,[2,4],true))fail(422,'VALIDATION_ERROR','The request contains invalid data.',['guideSearch.hours'=>['Expected 2 or 4 hours.']]);$people=(int)($search['people']??0);$max=(int)($data['maxPeople']??0);if($people<1||($max>0&&$people>$max))fail(409,'SERVICE_UNAVAILABLE','The guide cannot serve this party size.');$languages=$data['languages']??[];if($languages&&!in_array($search['language']??null,$languages,true))fail(409,'SERVICE_UNAVAILABLE','The selected language is not offered.');$amount=(int)round($amount*$hours/2);}
